import base64, json, os, subprocess, sys

D = "/content/work"
os.makedirs(D, exist_ok=True)
os.makedirs("/content/models", exist_ok=True)

FILES = json.loads(base64.b64decode('').decode("utf-8"))
for name, body in FILES.items():
    with open(f"{D}/{name}", "w", encoding="utf-8") as f:
        f.write(body)
    print(f"wrote {name} {len(body)} bytes", flush=True)

# results.jsonl is the checkpoint the runner reads. Written only if absent, so
# a re-exec of this bootstrap after the ladder has started cannot erase rows
# this VM measured.
if not os.path.exists(f"{D}/results.jsonl"):
    with open(f"{D}/results.jsonl", "w", encoding="utf-8") as f:
        f.write(FILES["seed-results.jsonl"])
    print("seeded results.jsonl", flush=True)
else:
    print(f"results.jsonl exists, {sum(1 for _ in open(D + '/results.jsonl'))} rows, left alone", flush=True)

# Detached, so every exec against this session stays short and the heartbeat's
# mutex is never held for the length of a run.
# The bracket is not decoration. `pgrep -f t4d_chain.py` matches the `sh -c`
# that pgrep itself runs, so a plain pattern always finds a match and the guard
# fires on its own command line -- which is exactly what happened at 19:03 UTC:
# the bootstrap printed "chain already running" with nothing running at all.
if subprocess.run("pgrep -f '[t]4d_chain.py'", shell=True, capture_output=True).returncode == 0:
    print("chain already running", flush=True)
else:
    out = open(f"{D}/run.out", "a")
    subprocess.Popen([sys.executable, f"{D}/t4d_chain.py"], stdout=out, stderr=subprocess.STDOUT,
                     cwd=D, start_new_session=True)
    print("chain launched", flush=True)
print("BOOTSTRAP_OK", flush=True)
